const e=[{id:1,icon:"Flame",emoji:"🔥",accent:"#dc2626",title:"Fire dangers",subtitle:"Be careful and keep yourself safe",summary:"Fire is very useful for cooking food and keeping the house warm, but if we are not careful, it can hurt us badly. Learning the fire rules shows how smart you are!",blocks:[{heading:"Matches and lighters are not toys",body:"Matches and lighters are only for grown-ups. Playing with them can start a fire very fast and burn you.",image:"media/images/fire_danger_1.png"},{heading:"Stay away from the heater",body:"Stay at least three steps away from the heater and from anything else that makes heat, so your clothes don't catch fire.",image:"media/images/fire_danger_2.png"},{heading:"Stop, drop and roll",body:"If your clothes catch fire: don't run! Stop, drop to the ground, cover your face with your hands and roll on the ground until the fire goes out. Then call a grown-up in a loud voice.",image:"media/images/fire_danger_3.png"}],examples:["When you see a fire, shout loudly: Fire! Fire! and move far away from that place.","Never play with a lighter, even if it is not lit.","If there is smoke in the room, get down low and crawl outside on your hands and knees."],video:"media/videos/lesson02_fire.mp4",game:{instruction:"Which of these things are dangerous?",items:[{text:"Matches",emoji:"🔥",correct:!0},{text:"Teddy bear",emoji:"🧸",correct:!1},{text:"Gas heater",emoji:"♨️",correct:!0},{text:"Book",emoji:"📚",correct:!1}]},activity:{prompt:"You go into the kitchen and see a piece of cloth that has fallen on the stove and is burning. What will you do?",image:"media/images/activity_fire.png",options:[{text:"I will leave the kitchen and tell Mom or Dad in a loud voice",correct:!0},{text:"I will try to put it out with my hands",correct:!1},{text:"I will stay there and watch",correct:!1},{text:"I will hide",correct:!1}]}},{id:2,icon:"Zap",emoji:"⚡",accent:"#ca8a04",title:"Electricity dangers",subtitle:"Electricity is not a toy, so be careful",summary:"Electricity is a power we cannot see. It makes our lights and TVs work. This power is very useful, but if we touch it the wrong way, it can badly hurt our heart and our body.",blocks:[{heading:"Don't touch electric sockets",body:"Electric sockets are only for the plugs of the machines we use at home. Never put beads, pencils or metal things into a socket, because the electricity will shock you.",image:"media/images/electricity_1.png"},{heading:"Water and electricity are enemies",body:"Water carries electricity very fast. Never touch light switches or electric wires with wet hands, or when you are in the bathroom.",image:"media/images/electricity_2.png"},{heading:"Cut wires and electric poles",body:"If you see a cut wire on the street or at home, don't go near it, and tell a grown-up right away. And when it is raining, don't touch the electric poles on the street.",image:"media/images/electricity_3.png"}],examples:["Never put a phone charger cable in your mouth.","Don't pull phone and iPad cables out of the socket. Tell a grown-up, and they will unplug them.","If you see a wire making sparks or a bad smell coming from it, tell Mom or Dad right away."],video:"media/videos/lesson02_electricity.mp4",game:{instruction:"Which of these things are safe to do?",items:[{text:"Playing with a plastic toy car",emoji:"🚗",correct:!0},{text:"Touching a cut wire",emoji:"⚡",correct:!1},{text:"Writing with a wooden pencil",emoji:"✏️",correct:!0},{text:"Putting a metal nail into a socket",emoji:"🔌",correct:!1}]},activity:{prompt:"You see your little brother on the floor, and he wants to put a phone charger cable in his mouth. What will you do?",image:"media/images/activity_electricity.png",options:[{text:"I will call the grown-ups loudly right away, so they take the cable away from him",correct:!0},{text:"I will wait until he takes it out",correct:!1},{text:"I will play with it with him too",correct:!1},{text:"I will hide",correct:!1}]}},{id:3,icon:"TrafficCone",emoji:"🚦",accent:"#2563eb",title:"Streets and cars",subtitle:"Staying safe on the street",summary:"The street is where big, fast cars come and go. To stay safe, we must learn the road rules well and never go onto the street alone.",blocks:[{heading:"Hold a grown-up's hand",body:"When you go outside, always hold the hand of Mom, Dad or another grown-up, so you stay safe and the cars can see you.",image:"media/images/traffic_1.png"},{heading:"Checking the street (left and right)",body:"Before you cross the street with a grown-up, stop! Look to the left, then to the right, then to the left again. If no cars are coming, walk straight across. Don't run and don't stop in the street.",image:"media/images/traffic_2.png"},{heading:"The language of traffic lights",body:"At the crossing, look at the light with the little person. Red person: we wait. Green person: we look left, right and left again, then walk across holding a grown-up's hand. Always cross at the crosswalk (the white stripes for walking).",image:"media/images/traffic_3.png"}],examples:["Never play with a ball or a scooter on the street.","In the car, always buckle your seat belt.","Don't play behind parked cars, because when the driver backs up, they can't see you."],video:"media/videos/lesson03_traffic.mp4",game:{instruction:"On the pedestrian light, which person tells you: Wait?",items:[{text:"Green person (cross with a grown-up)",emoji:"🟢",correct:!1},{text:"Red person (wait)",emoji:"🔴",correct:!0}]},activity:{prompt:"Your ball rolled away into the middle of the street, and there are lots of cars. What will you do?",image:"media/images/activity_traffic.png",options:[{text:"I don't go after it, and I call a grown-up right away to help me",correct:!0},{text:"I run fast after the ball",correct:!1},{text:"I wait until a car pops the ball",correct:!1},{text:"I cry and scream",correct:!1}]}},{id:4,icon:"Home",emoji:"🏠",accent:"#16a34a",title:"Earthquakes",subtitle:"How to keep yourself safe",summary:"Sometimes the ground shakes. This happens in nature, and it is called an earthquake. We need to stay calm and know how to keep ourselves safe.",blocks:[{heading:"Drop, Cover, Hold On",body:"If the ground shakes, get down on your knees right away, go under a strong table, protect your head and hold on tight to the table leg until the shaking stops.",image:"media/images/earthquake_1.png"},{heading:"Stay away from glass and windows",body:"In an earthquake, window glass and mirrors can break and hurt you, so stay away from them.",image:"media/images/earthquake_2.png"},{heading:"Don't run outside, and don't use the elevator",body:"While the ground is shaking, running outside is dangerous, because things may fall from the building onto you. And never use the elevator.",image:"media/images/earthquake_3.png"}],examples:["If there is no table, get down on your knees next to a wall, away from windows, and protect your head and neck with your hands.","Stay calm and don't scream, because being scared makes things harder for you.","After the shaking stops, leave the building slowly, together with the grown-ups."],video:"media/videos/lesson04_earthquake.mp4",game:{instruction:"In an earthquake, which of these places will keep you safe?",items:[{text:"Under a strong table",emoji:"🪑",correct:!0},{text:"Near glass windows",emoji:"🪟",correct:!1},{text:"Inside the elevator",emoji:"🛗",correct:!1},{text:"On the roof of the house",emoji:"🏠",correct:!1}]},activity:{prompt:"You are in your room and the house starts to shake. What will you do?",image:"media/images/activity_earthquake.png",options:[{text:"I go under the table, protect my head and hold on to the table leg",correct:!0},{text:"I run to the front door",correct:!1},{text:"I cry and stand there alone",correct:!1},{text:"I go to the window and look outside",correct:!1}]}},{id:5,icon:"Scissors",emoji:"✂️",accent:"#9333ea",title:"Sharp things that can hurt",subtitle:"Keep your body safe",summary:"Knives, scissors and all sharp things can easily cut our skin and make it bleed. These things are not toys, and they must only be used with care.",blocks:[{heading:"Knives are only for grown-ups",body:"Kitchen knives are very sharp, and only grown-ups use them. Never try to cut anything with a knife by yourself.",image:"media/images/sharp_1.png"},{heading:"Safe scissors for children",body:"If you use scissors for schoolwork, they must have a round tip and be made for children, so you don't get hurt.",image:"media/images/sharp_2.png"},{heading:"Glass and broken pieces",body:"If a glass or a mirror breaks, never touch it and don't step on it. Move away from that place right away and tell a grown-up, because small pieces of glass are very dangerous.",image:"media/images/sharp_3.png"}],examples:["Never run while you are holding something sharp.","Mom's needles and pins are not toys. Don't touch them.","If you get hurt, tell a grown-up right away so they can take care of you."],video:"media/videos/lesson05_sharp.mp4",game:{instruction:"Which of these things are dangerous, so we must not touch them?",items:[{text:"Knife",emoji:"🔪",correct:!0},{text:"Ball",emoji:"⚽",correct:!1},{text:"Colored pencils",emoji:"✏️",correct:!1},{text:"Teddy bear",emoji:"🧸",correct:!1}]},activity:{prompt:"You see a broken water glass on the floor, and nobody else is there. What will you do?",image:"media/images/activity_sharp.png",options:[{text:"I move away from that place, go to Mom or Dad and tell them, so they can clean it up",correct:!0},{text:"I pick up the pieces of glass with my hands",correct:!1},{text:"I step on it to find out if it is sharp",correct:!1},{text:"I push it under the carpet so nobody sees it",correct:!1}]}},{id:6,icon:"CookingPot",emoji:"🍳",accent:"#ea580c",title:"A safe kitchen",subtitle:"It is a place for food, not a place to play",summary:"The kitchen is the place in the house where yummy food is made, but it is full of heat, fire and boiling water that can hurt us.",blocks:[{heading:"The stove and the oven are hot",body:"When the stove is on, don't go near it. Its heat can burn you, even if you don't touch it.",image:"media/images/kitchen_1.png"},{heading:"Pots on the stove",body:"Never touch the handles of pots and never pull them. Grown-ups turn the handles in toward the middle of the stove, so the pots don't fall and the boiling water doesn't spill on you.",image:"media/images/kitchen_2.png"},{heading:"The kitchen is not a place to play",body:"Playing in the kitchen is dangerous, because you might fall onto the stove or onto a knife. The best places to play are your room or the living room.",image:"media/images/kitchen_3.png"}],examples:["Never touch a hot oven while bread is baking inside.","Be careful with boiling water and hot tea. They can burn you!","Don't run in the kitchen, because the floor is often slippery."],video:"media/videos/lesson06_kitchen.mp4",game:{instruction:"Which of these places are good for playing ball?",items:[{text:"The living room",emoji:"🛋️",correct:!0},{text:"On the stove",emoji:"🍳",correct:!1},{text:"The garden at home",emoji:"🌳",correct:!0},{text:"Inside the cooking pot",emoji:"🍲",correct:!1}]},activity:{prompt:"Your mom is cooking in the kitchen, and the stove is on. Where will you play?",image:"media/images/activity_kitchen.png",options:[{text:"I go to my room or the living room and play quietly",correct:!0},{text:"I go near the stove and play",correct:!1},{text:"I touch the pots to see what is inside",correct:!1},{text:"I throw my ball around in the kitchen",correct:!1}]}},{id:7,icon:"PlugZap",emoji:"💧",accent:"#0891b2",title:"Water and electricity: two big enemies",subtitle:"Keep yourself safe from electric shocks",summary:"Water and electricity must never meet. Water carries electricity fast, and if your body is wet, the electricity will shock you even harder and badly hurt your heart.",blocks:[{heading:"Always with dry hands",body:"Before you touch a light switch, your hands must be completely dry, with no water on them.",image:"media/images/water_elec_1.png"},{heading:"The bathroom and electronic devices",body:"Never take a phone, an iPad or anything else that works with electricity into the bathroom, especially while it is charging, because water and steam can carry the electricity to you.",image:"media/images/water_elec_2.png"},{heading:"Water spilled on wires",body:"If you see water spilled on an electric wire or a socket, don't go near it, and tell the grown-ups right away so they can turn off the electricity.",image:"media/images/water_elec_3.png"}],examples:["Don't use the hair dryer (the machine that dries your hair) by yourself, and never take it near water.","If you are at a swimming pool or near a pond, don't touch any lights or electric devices.","If the floor is wet, don't go near electric devices, and tell a grown-up."],video:"media/videos/lesson07_water_elec.mp4",game:{instruction:"What is the right way to touch a light switch?",items:[{text:"With wet, dripping hands",emoji:"💦",correct:!1},{text:"With clean, dry hands",emoji:"✋",correct:!0},{text:"With soapy hands",emoji:"🧼",correct:!1},{text:"While sitting in the bathtub",emoji:"🛁",correct:!1}]},activity:{prompt:"You have just come out of the bathroom and your hands are wet. You want to turn on the light in your room. What will you do?",image:"media/images/activity_water_elec.png",options:[{text:"First I dry my hands with a towel, then I turn on the light",correct:!0},{text:"I touch the light switch while my hands are still wet",correct:!1},{text:"I wipe my hands on my clothes and then touch it",correct:!1},{text:"I shout until somebody comes and turns it on for me",correct:!1}]}},{id:8,icon:"Building",emoji:"🧗",accent:"#4f46e5",title:"Dangers of high places",subtitle:"Keep yourself from falling",summary:"Climbing onto high tables and walls is not a game. Your body is delicate, and falling from a high place can break your bones and hurt you a lot.",blocks:[{heading:"Tables and chairs are for sitting",body:"Chairs are for sitting and tables are for eating. They are not for standing on or for climbing up onto cupboards.",image:"media/images/heights_1.png"},{heading:"Balconies and windows are dangerous",body:"Never lean out of a window or over a balcony wall, because you can easily lose your balance and fall.",image:"media/images/heights_2.png"},{heading:"Play on the ground",body:"Always play on the floor or in the garden, so that even if you fall, you don't get hurt.",image:"media/images/heights_3.png"}],examples:["Don't jump on the sofa or on the bed, because you could fall on your head.","Never climb onto chairs near the window to look outside.","If something of yours is up high, don't try to reach it by yourself. Tell Dad or Mom."],video:"media/videos/lesson08_heights.mp4",game:{instruction:"Which of these places is safe for playing?",items:[{text:"On the balcony wall",emoji:"🧱",correct:!1},{text:"On the carpet in your room",emoji:"🏃",correct:!0},{text:"On the dining table",emoji:"🪟",correct:!1},{text:"On tree branches",emoji:"🌳",correct:!1}]},activity:{prompt:"Your favorite toy is on top of a high cupboard, and you can't reach it. What will you do?",image:"media/images/activity_heights.png",options:[{text:"I will tell a grown-up and wait calmly until they get it down for me",correct:!0},{text:"I will climb up the cupboard myself",correct:!1},{text:"I will put some chairs on top of each other so I can reach it",correct:!1},{text:"I will hit it with a stick until it falls down and breaks",correct:!1}]}},{id:9,icon:"Candy",emoji:"🍬",accent:"#db2777",title:"Dangers of swallowing things",subtitle:"Small things and choking",summary:"Our mouth is for eating and drinking. We must be very careful not to put other things in our mouth, because some things can block the way we breathe and make us choke.",blocks:[{heading:"Coins and beads",body:"Coins, beads and the small batteries from watches are not food. If these things go down your throat, they are very dangerous.",image:"media/images/swallow_1.png"},{heading:"Medicine is not candy",body:"Medicine pills have pretty colors and look like candy, but if you eat them by yourself, they will poison you. Only take medicine when Mom or Dad gives it to you.",image:"media/images/swallow_2.png"},{heading:"Keeping your breathing safe",body:"Anything that is not food and goes into your mouth can get stuck in your throat and stop you from breathing. Always keep small things away from your mouth.",image:"media/images/swallow_3.png"}],examples:["Don't put a pen cap in your mouth, because it can easily slip down your throat.","Don't swallow fruit pits (like apricot pits and olive pits). Take them out of your mouth right away.","If you swallow something, tell a grown-up right away, even if you feel fine."],video:"media/videos/lesson09_swallow.mp4",game:{instruction:"Which of these things are good to eat?",items:[{text:"Apples and fruit",emoji:"🍎",correct:!0},{text:"A coin",emoji:"🪙",correct:!1},{text:"Colorful beads",emoji:"📿",correct:!1},{text:"Bread and bread rolls",emoji:"🍞",correct:!0}]},activity:{prompt:"You see your little sister put a small toy battery in her mouth. What will you do?",image:"media/images/activity_swallow.png",options:[{text:"I call Mom loudly right away and tell her what my sister put in her mouth",correct:!0},{text:"I will laugh and watch",correct:!1},{text:"I will put one in my mouth too",correct:!1},{text:"I will wait until my sister swallows it",correct:!1}]}},{id:10,icon:"MapPin",emoji:"🗺️",accent:"#9333ea",title:"Getting lost in busy places",subtitle:"If you get separated from your mom and dad",summary:"If you get separated from your family and get lost at the market, at the mall or on a picnic, don't be scared. You just need to know what to do, so Mom and Dad can find you again as quickly as possible.",blocks:[{heading:"Stay where you are",body:"If you see that Mom and Dad are not around you, don't run and don't go looking for them. Stay where you are, because they will come back to that place very soon to look for you and find you.",image:"media/images/lost_1.png"},{heading:"Ask for help",body:"If nobody comes, find someone near you: a police officer, a mall guard, a shop worker or a mom with children, and tell them: I am lost.",image:"media/images/lost_2.png"},{heading:"Your important information",body:"Try to learn your full name and Mom's or Dad's phone number by heart, so the people helping you can call them.",image:"media/images/lost_3.png"}],examples:["Never let go of Mom's hand at the market.","Never go anywhere with strangers, even if they give you candy.","Stay calm and don't cry, because being scared stops you from thinking well.","Stay in bright places where there are people, and don't go into dark alleys."],video:"media/videos/lesson10_lost.mp4",game:{instruction:"If you are lost, who can help you?",items:[{text:"A police officer or a guard",emoji:"👮‍♂️",correct:!0},{text:"A stranger",emoji:"👤",correct:!1},{text:"A mom with her children",emoji:"👩‍👧‍👦",correct:!0},{text:"A scary man",emoji:"🦹‍♂️",correct:!1}]},activity:{prompt:"You are lost in a mall and you can't see your mom and dad. What will you do?",image:"media/images/activity_lost.png",options:[{text:"I stay where I am and don't go anywhere until they come, or I tell a person I can trust",correct:!0},{text:"I run to the mall door and go outside",correct:!1},{text:"I go with a stranger because he says he will take me to them",correct:!1},{text:"I go under a chair and hide",correct:!1}]}},{id:11,icon:"Baby",emoji:"🎡",accent:"#65a30d",title:"Safety at the playground",subtitle:"Playing nicely and safely",summary:"The playground is a lovely place to play and make new friends, but so that nobody gets hurt, we need to follow some golden rules.",blocks:[{heading:"Don't push your friends",body:"Never push your friends on the swing or on the slide, because falling onto stones or hard ground can cause bad injuries.",image:"media/images/playground_1.png"},{heading:"Lining up and taking turns",body:"Learn to wait for your turn. Taking turns shows that you are smart and that you respect your friends.",image:"media/images/playground_2.png"},{heading:"The edges of the playground",body:"Never go outside the playground fence. If your ball goes outside, don't go after it alone. Tell Mom or your teacher.",image:"media/images/playground_3.png"}],examples:["Don't throw sand into the air, because it gets into your friends' eyes.","Don't stand in front of a swing while it is moving, so it doesn't hit you.","If you see that something to play on is broken, don't play on it, and tell the person in charge of the playground."],video:"media/videos/lesson11_playground.mp4",game:{instruction:"Which of these are things a safety hero does?",items:[{text:"Pushing friends to get ahead in line",emoji:"✋",correct:!1},{text:"Waiting calmly in line",emoji:"⏱️",correct:!0},{text:"Fighting over toys",emoji:"🥊",correct:!1},{text:"Helping younger friends",emoji:"🤝",correct:!0}]},activity:{prompt:"A friend of yours is in front of you and wants to go up and play. What will you do?",image:"media/images/activity_playground.png",options:[{text:"I will wait calmly until it is my turn",correct:!0},{text:"I will push my friend so I can go up first",correct:!1},{text:"I will shout and scream",correct:!1},{text:"I will go somewhere else and cut the fence",correct:!1}]}},{id:12,icon:"Dog",emoji:"🐕",accent:"#d97706",title:"Street animals and animals you don't know",subtitle:"How to behave around dogs and cats",summary:"Animals that wander the streets, whose owners we don't know, can be dangerous. Some of them are scared or sick, and they may bite people.",blocks:[{heading:"Don't touch animals you don't know",body:"Even if a cat or a dog looks very cute, don't touch it. It might bite you or scratch you with its claws, and animals can pass sicknesses on to you.",image:"media/images/dogs_1.png"},{heading:"Stand still like a tree",body:"If a dog comes toward you: don't run! Stand quietly like a tree, keep your hands close to your body and don't look into the dog's eyes, until it goes away.",image:"media/images/dogs_2.png"},{heading:"Tell a grown-up",body:"If you see a hurt or angry animal near your home, don't go near it, and tell Dad or Mom right away. If an animal bites you or scratches you with its claws, tell a grown-up right away so they can take you to the doctor.",image:"media/images/dogs_3.png"}],examples:["Never throw stones or other things at animals, because they will get angry and attack you.","Don't go near animals while they are eating or sleeping.","Don't pull cats' tails or ears, because they will scratch you."],video:"media/videos/lesson12_dogs.mp4",game:{instruction:"If a dog you don't know comes toward you, what will you do?",items:[{text:"I will run away fast",emoji:"🏃",correct:!1},{text:"I will throw stones at it",emoji:"🪨",correct:!1},{text:"I will stand quietly like a tree",emoji:"🧍",correct:!0},{text:"I will shout and wave my arms",emoji:"🗣️",correct:!1}]},activity:{prompt:"A little kitten is crying on the street. What will you do?",image:"media/images/activity_dogs.png",options:[{text:"I watch from far away and tell Mom, so she can help it",correct:!0},{text:"I go and hug it right away",correct:!1},{text:"I push it with my foot",correct:!1},{text:"I chase it and make it run away",correct:!1}]}},{id:13,icon:"Wind",emoji:"👃",accent:"#475569",title:"The smell of gas and its dangers",subtitle:"Smells can warn us",summary:"Some smells in the house are like a warning bell. The smell of gas or the smell of something burning tells us that there is a big danger.",blocks:[{heading:"The rotten-egg smell (gas)",body:"Gas itself has no smell, but people add a bad smell to it on purpose, so we know when gas is leaking out. If you smell gas, don't touch any light switches.",image:"media/images/gas_1.png"},{heading:"Get out first",body:"Don't stop to open windows. Go outside right away and tell a grown-up. Children never touch the gas.",image:"media/images/gas_2.png"},{heading:"Get out of the building",body:"Don't stay where the smell is. Go outside right away and tell a grown-up. Grown-ups call 115 from outside, not from inside the house.",image:"media/images/gas_3.png"}],examples:["Never play with the gas valves and knobs.","Don't stay in closed car garages, because the smoke from cars is poisonous.","If you smell electric wires burning, tell Dad or Mom right away."],video:"media/videos/lesson13_gas.mp4",game:{instruction:"If you smell gas in the kitchen, what will you do?",items:[{text:"I will turn on the light to see what happened",emoji:"💡",correct:!1},{text:"I will tell a grown-up",emoji:"🗣️",correct:!0},{text:"I will light a match",emoji:"🔥",correct:!1},{text:"I will leave the house and go outside",emoji:"🚪",correct:!0}]},activity:{prompt:"You are in the kitchen, and there is a strong smell of gas. What will you do?",image:"media/images/activity_gas.png",options:[{text:"I go outside right away and tell a grown-up",correct:!0},{text:"I go near the stove to find out where the gas is coming from",correct:!1},{text:"I turn on the fan so the smell goes away",correct:!1},{text:"I do nothing and stay where I am",correct:!1}]}},{id:14,icon:"FlaskConical",emoji:"🧴",accent:"#0d9488",title:"Bottles and liquids you don't know",subtitle:"Don't taste, don't drink",summary:"At home there are lots of colorful containers and bottles. Their colors look as pretty as juice, but really they have chemicals and poisons inside that are used for cleaning.",blocks:[{heading:"Don't drink it, don't taste it",body:"Never taste or drink any liquid you don't know. It might be a cleaner for the bathroom or the floor, and it can hurt your body.",image:"media/images/poison_1.png"},{heading:"Always ask",body:"Before you eat or drink something you don't know, ask Mom or Dad: Is this OK to eat? If they don't say yes, don't touch it.",image:"media/images/poison_2.png"},{heading:"Cleaning products are dangerous",body:"Bleach and other cleaning products are only for cleaning the house. Some of them can burn your skin and eyes, or poison you.",image:"media/images/poison_3.png"}],examples:["Sprays for bugs, flies and ants are poison. Never smell them.","Bottles of cleaning products at home are not toys. Don't touch them.","If you drink something you don't know, tell Mom or Dad right away, so they can call the ambulance (122)."],video:"media/videos/lesson14_poison.mp4",game:{instruction:"Which of these things are good to drink?",items:[{text:"Orange juice",emoji:"🧃",correct:!0},{text:"Floor cleaner",emoji:"🧴",correct:!1},{text:"Bleach",emoji:"🧪",correct:!1},{text:"Milk",emoji:"🥛",correct:!0}]},activity:{prompt:"You found a pretty blue bottle under the sink, and you are thirsty. What will you do?",image:"media/images/activity_poison.png",options:[{text:"I don't touch it. I go to Mom and ask her",correct:!0},{text:"I taste a little to find out what it is",correct:!1},{text:"I pour it on the floor and play with it",correct:!1},{text:"I pour it into a glass and drink it",correct:!1}]}},{id:15,icon:"CloudRain",emoji:"🌧️",accent:"#0284c7",title:"Rain and the danger of floods",subtitle:"Keep yourself safe from flood water",summary:"Rain is very good for plants and for the land, but if it rains very hard, it can turn into a flood. Flood water is very strong, and it can put our lives in danger.",blocks:[{heading:"Stay inside the house",body:"When it is raining hard, the best and safest place is inside the house. Don't play outside in heavy rain.",image:"media/images/flood_1.png"},{heading:"Don't go into the water on the street",body:"Flood water is dirty and carries germs that make people sick. It is also very strong: even a little water can knock you down and carry you away.",image:"media/images/flood_2.png"},{heading:"Stay away from rivers and streams",body:"When it rains, the water in rivers and streams rises very fast. Always stay far away from the edge of the water.",image:"media/images/flood_3.png"}],examples:["If it rains very hard and the water rises, go with the grown-ups from low places up to high places.","When it rains, use an umbrella so your body stays dry.","When it rains, wear rubber boots, but never walk into flood water."],video:"media/videos/lesson15_flood.mp4",game:{instruction:"When it is raining very hard, which place is the safest of all?",items:[{text:"In the garden",emoji:"🏕️",correct:!1},{text:"Inside the house",emoji:"🏠",correct:!0},{text:"In the river",emoji:"🌊",correct:!1},{text:"On the street",emoji:"🛣️",correct:!1}]},activity:{prompt:"You go outside and see that the whole street has turned into water, like a flood. What will you do?",image:"media/images/activity_flood.png",options:[{text:"I don't go into the water. I go back inside the house and tell the grown-ups",correct:!0},{text:"I go into the water on the street and swim",correct:!1},{text:"I just put my feet in the water and play",correct:!1},{text:"I throw my ball into the water so the water carries it away",correct:!1}]}},{id:16,icon:"Bus",emoji:"🚌",accent:"#ca8a04",title:"Big vehicles and blind spots",subtitle:"Keep away from the danger zones",summary:"Trucks, buses and other big vehicles are not like small cars. Their drivers cannot see some places around the vehicle. These places are called blind spots (No-Zone). If you are there, the driver can't see you, and the vehicle might hit you.",blocks:[{heading:"The no-go zone (No-Zone)",body:"There are blind spots behind a truck, in front of it and on both of its sides. If you can't see the driver's eyes in the mirror, the driver can't see you either. Stay away from trucks and buses.",image:"media/images/car_back_1.png"},{heading:"Under a car is not a place to play",body:"If your ball or toy goes under a car (even a parked car), never go under the car. Call a grown-up right away to get it out for you.",image:"media/images/car_back_2.png"},{heading:"Room to turn",body:"When trucks and buses turn, they need lots of space, and they often go up onto the sidewalk too. Always stand three steps back from the edge of the street.",image:"media/images/car_back_3.png"}],examples:["Never put your hand or your head out of a bus window or a car window.","A garage is not a place to play, because cars back up there and the drivers can't see you.","Always wait until the bus has stopped completely, then get off."],video:"media/videos/lesson16_car_back.mp4",game:{instruction:"Which places near big vehicles are dangerous?",items:[{text:"Right behind the truck",emoji:"🚘",correct:!0},{text:"In the garden",emoji:"🌳",correct:!1},{text:"Right in front of the truck",emoji:"🚚",correct:!0},{text:"10 meters away",emoji:"🏠",correct:!1}]},activity:{prompt:"Your ball rolled away under a big truck, and the driver is inside. What will you do?",image:"media/images/activity_car_back.png",options:[{text:"I don't go under the truck. I go to Dad so he can get it out for me",correct:!0},{text:"I quickly go under the truck, because the driver is asleep",correct:!1},{text:"I hit the ball with a long stick until it comes out",correct:!1},{text:"I cry until the driver gives me the ball himself",correct:!1}]}},{id:17,icon:"Car",emoji:"🎗️",accent:"#4f46e5",title:"Seat belts and airbags",subtitle:"Staying safe inside the car",summary:"A seat belt is like a strong hug that holds you in your seat. If the car stops suddenly, the belt stops your body from hitting things hard.",blocks:[{heading:"Always buckle up",body:"Before the car moves, you must be in a child car seat with your belt buckled the right way. This shows how smart you are.",image:"media/images/seatbelt_1.png"},{heading:"Children sit in the back",body:"Children younger than 13 must always sit in the back seats. In the front there is an airbag (a bag that fills with air), and when it pops open very fast, it can hurt children.",image:"media/images/seatbelt_2.png"},{heading:"Don't move until the car stops",body:"Never unbuckle your belt or leave your seat until the car has stopped completely and the driver tells you it is OK.",image:"media/images/seatbelt_3.png"}],examples:["Never open the car door while the car is moving.","While the car is moving, don't talk loudly to the driver, so the driver can keep their mind on the road.","Don't play wild games in the back seat, so the driver doesn't get distracted."],video:"media/videos/lesson17_seatbelt.mp4",game:{instruction:"Which of these are the right things to do in the car?",items:[{text:"Buckling your seat belt",emoji:"✅",correct:!0},{text:"Putting your head out of the window",emoji:"🤪",correct:!1},{text:"Sitting in the back seat",emoji:"💺",correct:!0},{text:"Opening the door while the car is moving",emoji:"🚪",correct:!1}]},activity:{prompt:"You get into the car, and you want to sit in the front seat. What will you do?",image:"media/images/activity_seatbelt.png",options:[{text:"I go to the back seat and buckle my belt, because it is safer for children",correct:!0},{text:"I cry so my dad lets me sit in the front",correct:!1},{text:"I don't buckle my belt, because it is too tight",correct:!1},{text:"While the car is moving, I will open the door",correct:!1}]}},{id:18,icon:"AlertTriangle",emoji:"☢️",accent:"#dc2626",title:"Danger signs around the world",subtitle:"Learn the language of pictures",summary:"All around the world, special pictures and signs are used to warn us about danger without any words. Knowing these signs shows how smart you are.",blocks:[{heading:"Skull and bones (poison)",body:"This sign (☠️) means poisonous things that can kill. If something has this picture on it, never touch it and don't go near it.",image:"media/images/danger_signs_1.png"},{heading:"The flame sign (burns easily)",body:"This picture shows that the thing catches fire very fast. It must be kept away from fire and heat, and you must not touch it either.",image:"media/images/danger_signs_2.png"},{heading:"The yellow lightning bolt (strong electricity)",body:"This sign shows that there is very strong electricity in this place, and it can kill people. Never go near that place.",image:"media/images/danger_signs_3.png"}],examples:["A red X sign says: This is not allowed.","The radiation sign (☢️) can be seen in some places in hospitals. Stay away from those places.","Round blue signs tell us safety rules, and we must do what they say."],video:"media/videos/lesson18_danger_signs.mp4",game:{instruction:"What does this sign (☠️) tell us?",items:[{text:"Poisonous things that can kill",emoji:"🧪",correct:!0},{text:"Clean water to drink",emoji:"💧",correct:!1},{text:"Yummy food",emoji:"🍕",correct:!1},{text:"A play area for children",emoji:"🎮",correct:!1}]},activity:{prompt:"You see a picture of a skull and bones on the door of a storeroom. What will you do?",image:"media/images/activity_danger_signs.png",options:[{text:"I move away from it right away, don't go near the door and tell a grown-up",correct:!0},{text:"I go inside to see what is in there",correct:!1},{text:"I throw stones at the door",correct:!1},{text:"I play by the door, because the picture looks interesting",correct:!1}]}},{id:19,icon:"Award",emoji:"🏆",accent:"#ca8a04",title:"The safety hero and responsibility",subtitle:"Now you know a lot and you are doing great",summary:"Well done! You have learned lots of safety rules. Now you are not just a child: you are a safety hero in our community.",blocks:[{heading:"You are alert and careful",body:"Now you know how to keep yourself safe from the dangers of fire, electricity, floods and the street. This is your real power.",image:"media/images/hero_1.png"},{heading:"Help other people",body:"Your job as a hero is to tell your friends, sisters and brothers what you have learned too, so everyone stays safe.",image:"media/images/hero_2.png"},{heading:"Following safety instructions",body:"Always listen to your mom and dad, your teachers and the Civil Defense teams. Safety rules are there to protect our lives.",image:"media/images/hero_3.png"}],examples:["Before you do anything, always think: Is this safe?","If you see a danger, tell a grown-up without being afraid.","You show all your friends how to be smart."],video:"media/videos/lesson19_hero.mp4",game:{instruction:"What are the right things a safety hero does?",items:[{text:"Keeping yourself and others safe",emoji:"🛡️",correct:!0},{text:"Playing with matches and lighters",emoji:"🔥",correct:!1},{text:"Helping family and friends",emoji:"🤝",correct:!0},{text:"Fighting with friends",emoji:"👊",correct:!1}]},activity:{prompt:"You see that a friend of yours in the garden wants to play with a cut electric wire. What will you do?",image:"media/images/activity_hero.png",options:[{text:"I will tell my friend: Don't go near it! And I will tell the teacher or Mom right away",correct:!0},{text:"I will play with it with my friend too",correct:!1},{text:"I will hit my friend to make them stop",correct:!1},{text:"I will stay quiet and say nothing",correct:!1}]}},{id:20,icon:"Truck",emoji:"🚒",accent:"#dc2626",title:"Firefighting heroes",subtitle:"The people who work at the Civil Defense Directorate",summary:"The people who work for Civil Defense are heroes. They have done hard training, so they can put out fires and save the lives of people and animals in emergencies.",blocks:[{heading:"The red fire truck",body:"The fire truck is red, and it carries water, ladders and rescue tools. When you hear its alarm (the siren), everyone must make way for it.",image:"media/images/firefighters_1.png"},{heading:"Protective clothes",body:"Firefighters wear special clothes that don't catch fire and that keep the heat away from their bodies. Their helmets and boots are very strong too.",image:"media/images/firefighters_2.png"},{heading:"Helpers in our community",body:"Firefighters are our friends. When there is danger, they come to protect us. Don't be scared of their sounds, their clothes or their masks, and don't hide from them, because they are coming to save you.",image:"media/images/firefighters_3.png"}],examples:["When you hear the sound of a fire truck, move away from the street and stand at the side.","Firefighters don't only put out fires. They also rescue people who are trapped.","They do a very special and important job to protect the people of the city."],video:"media/videos/lesson20_firefighters.mp4",game:{instruction:"Which of these things belong to firefighters?",items:[{text:"The red fire truck",emoji:"🚒",correct:!0},{text:"The city bus",emoji:"🚌",correct:!1},{text:"A hard helmet and firefighter clothes",emoji:"🧑‍🚒",correct:!0},{text:"A toy cat",emoji:"🐱",correct:!1}]},activity:{prompt:"You see a red fire truck coming fast with its siren on. What will you do?",image:"media/images/activity_firefighters.png",options:[{text:"I move away from the street and stand at the side until the truck has gone past",correct:!0},{text:"I go into the middle of the street to take a picture",correct:!1},{text:"I run toward the truck",correct:!1},{text:"I throw stones at the truck",correct:!1}]}},{id:21,icon:"PhoneCall",emoji:"📞",accent:"#2563eb",title:"The emergency number 115",subtitle:"Calling Civil Defense",summary:"115 is the Civil Defense number. When a fire or a disaster happens, someone calls this number, and the firefighters come fast. Every child should learn this number by heart.",blocks:[{heading:"115 is for emergencies",body:"If you see a fire, or someone is trapped under fallen pieces of a building, or a flood comes, tell a grown-up right away so they can call 115. If there is no grown-up with you, call 115 yourself from a safe place. For people who are hurt or sick, grown-ups call the ambulance (122).",image:"media/images/emergency_number_1.png"},{heading:"Talking the right way",body:"When you call, speak calmly and say your name, where you are and what happened.",image:"media/images/emergency_number_2.png"},{heading:"No playing with this number",body:"Calling 115 is only for real emergencies. Playing with this number is not allowed, because then the team might be late getting to people who need help.",image:"media/images/emergency_number_3.png"}],examples:["Learn the number 115 by heart: one, one, five.","115 is called only when there is a real danger.","When you are talking to 115, don't hang up until the person on the phone tells you to."],video:"media/videos/lesson21_emergency_number.mp4",game:{instruction:"What is the official Civil Defense number in Duhok?",items:[{text:"123",emoji:"📱",correct:!1},{text:"115",emoji:"🚒",correct:!0},{text:"999",emoji:"📞",correct:!1},{text:"444",emoji:"☎️",correct:!1}]},activity:{prompt:"Out on the street, you see smoke and notice a strong burning smell coming from a house. What will you do?",image:"media/images/activity_emergency_number.png",options:[{text:"I tell a grown-up right away so they can call 115. If nobody is there, I call 115 myself",correct:!0},{text:"I stay where I am and cry",correct:!1},{text:"I go into that house to see what is happening",correct:!1},{text:"I hide so the police don't catch me",correct:!1}]}},{id:22,icon:"DoorOpen",emoji:"🚪",accent:"#16a34a",title:"Emergency escape plan",subtitle:"Getting out quickly and calmly",summary:"An escape plan is a map. It shows which way we go out and where we all meet when there is a fire or another danger. Every home and every school should have this plan, so everyone can get out calmly.",blocks:[{heading:"Two ways out",body:"Every room should have two ways out. If the first way is blocked, use the second way, together with the grown-ups.",image:"media/images/evacuation_1.png"},{heading:"The meeting point",body:"After you get out of the building, go to the meeting point: an open, safe place that was chosen before. Stay there, so the grown-ups know that everyone got out.",image:"media/images/evacuation_2.png"},{heading:"The golden rule: don't go back inside",body:"Once you are out of the building, never go back inside, not for toys and not for anything else. Your life is more important than anything.",image:"media/images/evacuation_3.png"}],examples:["At least twice a year, practice getting out of the house with your family.","In big public buildings, look for the green exit signs (EXIT).","If there is smoke, crawl on your hands and knees, because the cleaner air is near the floor."],video:"media/videos/lesson22_evacuation.mp4",game:{instruction:"When getting out, which of these are the right things to do?",items:[{text:"Knowing the ways out",emoji:"🚪",correct:!0},{text:"Going back into the building to get your toys",emoji:"🧸",correct:!1},{text:"Staying at the meeting point",emoji:"📍",correct:!0},{text:"Staying in the room until the team comes",emoji:"🛋️",correct:!1}]},activity:{prompt:"The fire alarm rang at school, and your toys are still in the classroom. What will you do?",image:"media/images/activity_evacuation.png",options:[{text:"Calmly, without pushing my friends, I go out through the exit door with the teacher",correct:!0},{text:"I go back to the classroom to get my toys",correct:!1},{text:"I go under a table and hide",correct:!1},{text:"I run to the elevator, screaming",correct:!1}]}},{id:23,icon:"FireExtinguisher",emoji:"🧯",accent:"#ea580c",title:"Firefighting tools and equipment",subtitle:"The firefighters' tools",summary:"Civil Defense teams use very modern tools to put out fires and rescue people. These tools are only for grown-ups and firefighters. Children don't touch them.",blocks:[{heading:"The fire extinguisher",body:"A fire extinguisher is a bottle under pressure, with water, powder or CO₂ gas inside. Only grown-ups use it. Children never touch it.",image:"media/images/fire_equipment_1.png"},{heading:"Strong water hoses",body:"Firefighters use very strong hoses that shoot out water with a lot of force and put out the fire.",image:"media/images/fire_equipment_2.png"},{heading:"Cutting and rescue tools",body:"These are very strong tools. Firefighters use them to cut through the metal of cars, so they can rescue people who are trapped or hurt.",image:"media/images/fire_equipment_3.png"}],examples:["Never touch a fire extinguisher, because there is strong pressure inside it.","Know where the fire extinguisher is at home and at school, but don't touch it.","If there is a big fire, everyone leaves the building, and only the firefighters use their tools."],video:"media/videos/lesson23_fire_equipment.mp4",game:{instruction:"Which of these tools are used to put out fires?",items:[{text:"Fire extinguisher",emoji:"🧯",correct:!0},{text:"A toy ball",emoji:"⚽",correct:!1},{text:"Firefighters' water hoses",emoji:"💦",correct:!0},{text:"Books for reading",emoji:"📚",correct:!1}]},activity:{prompt:"A small fire started in the kitchen trash can, and your dad is at home. What will you do?",image:"media/images/activity_fire_equipment.png",options:[{text:"I leave the kitchen and call my dad loudly, so he can put out the fire",correct:!0},{text:"I will pick up the fire extinguisher and play with it",correct:!1},{text:"I pour water on the fire myself",correct:!1},{text:"I go to another room and hide",correct:!1}]}},{id:24,icon:"CloudFog",emoji:"💨",accent:"#475569",title:"The danger of smoke and breathing clean air",subtitle:"How to get out of smoke safely",summary:"The smoke from a fire is often more dangerous than the fire itself, because it is poisonous and makes it hard to breathe. Smoke and heat go up, so the cleaner air is near the floor. Get low and get out: this will save your life.",blocks:[{heading:"Get low and crawl",body:"Heat and smoke always go up, so the cleaner air stays near the floor. Crawl on your hands and knees and keep your head low until you get outside. Never walk standing up through smoke.",image:"media/images/smoke_1.png"},{heading:"Covering your mouth and nose",body:"If you have a piece of cloth with you, cover your mouth and nose with it. But don't stop to look for a cloth, because cloth doesn't block all the smoke. Get low right away and get out.",image:"media/images/smoke_2.png"},{heading:"Test the door before you open it",body:"Before you open a door, touch the door and its handle with the back of your hand. If it is hot, or smoke is coming from under the door, don't open it. Use another way out.",image:"media/images/smoke_check_door.png"},{heading:"Close the door behind you",body:"When you leave a room, close the door behind you. A closed door stops fire and smoke from spreading fast to other places.",image:"media/images/smoke_3.png"},{heading:"Don't open windows if you don't need to",body:"Air makes a fire bigger, so don't open windows and doors if you don't need to. If you are stuck in a room, keep the door closed, go to the window, wave your hand and shout, so the firefighters can see you. Never jump out of the window.",image:"media/images/smoke_no_window.png"}],reference:[{heading:"The main rules",points:["✅ Get low and crawl on your hands and knees.","✅ Know the ways out of your home.","✅ Before you open a door, test it with the back of your hand, and if it is hot, don't open it.","✅ Close the door behind you.","❌ Don't hide under the bed or in the cupboard, and don't go back inside."]},{heading:"After you get out",points:["🌿 Go to the meeting point and stay outside.","📞 Tell a grown-up. Grown-ups call 115 from outside, and they also call 122 if someone is hurt.","⚠️ If your head hurts, you feel dizzy or it is hard to breathe, tell a grown-up right away so they can call the ambulance (122)."]}],examples:["When you see smoke, shout: Fire! Then get low and crawl toward the way out.","If it is dark, stay on your hands and knees, keep one hand on the wall and crawl low to the exit door.","If the door is hot, don't open it. Use another way out.","If you can't get out: close the door, put a towel under the door, wave your hand at the window and shout. If you have a phone with you, call 115 and say where you are."],video:"media/videos/lesson24_smoke.mp4",game:{instruction:"If there is black smoke in the room, what will you do? (Choose all the right answers)",items:[{text:"I stand up and stay where I am",emoji:"🧍",correct:!1},{text:"I get low and crawl on my hands and knees",emoji:"🧎",correct:!0},{text:"I open the windows to let air in",emoji:"🪟",correct:!1},{text:"If I have a piece of cloth, I cover my mouth and nose with it",emoji:"🧣",correct:!0},{text:"Before I open a door, I test it with the back of my hand",emoji:"🖐️",correct:!0},{text:"I close the door behind me",emoji:"🚪",correct:!0}]},activity:{prompt:"You are in your bedroom, and black smoke is coming in under the door. The door is very hot. What will you do?",image:"media/images/activity_smoke.png",options:[{text:"I don't open the door. I get low, go to the window, wave my hand and shout, so the grown-ups and firefighters can see me",correct:!0},{text:"I open the door and run outside standing up",correct:!1},{text:"I open all the windows and doors so the fire gets smaller",correct:!1},{text:"I hide under the bed",correct:!1}]}},{id:25,icon:"Siren",emoji:"🚒",accent:"#dc2626",title:"Our brave firefighters",subtitle:"Who is in the red truck?",summary:"When a fire starts or an accident happens, the Civil Defense heroes come in the red truck! They keep people safe. Their number is 115, and every child should know this number.",blocks:[{heading:"The red truck",body:"The firefighters' truck is big and red, and it has a siren. It carries water, hoses, ladders and rescue tools. When you see it, move away from the street and leave the way clear for it.",image:"media/images/cd_truck.png"},{heading:"The heroes' siren",body:`The siren goes "Wooo-wooo-wooo." It is saying: "We are coming, make way!" Don't be scared of it. They are coming to help us.`,image:"media/images/cd_siren.png"},{heading:"115 is an important number",body:"If you see a fire or an accident, tell a grown-up right away so they can call 115. If you are alone, press 1-1-5 on the phone and say your name and where you are.",image:"media/images/cd_phone.png"}],examples:["Firefighters wear special clothes and helmets, so the fire doesn't burn them.","When the red truck comes, our car must move to the side and leave the way clear for it.","Calling 115 is not a game. It is only for real emergencies."],video:"media/videos/lesson25_heroes.mp4",game:{instruction:"What do the Civil Defense heroes do?",items:[{text:"They put out fires",emoji:"🔥",correct:!0},{text:"They sell pizza",emoji:"🍕",correct:!1},{text:"They rescue people who are trapped",emoji:"🆘",correct:!0},{text:"They play soccer",emoji:"⚽",correct:!1},{text:"They climb ladders to rescue people",emoji:"🪜",correct:!0}]},activity:{prompt:"You are at the window. You see the red truck on the street and hear the siren. What will you do?",image:"media/images/activity_truck.png",options:[{text:"I stay where I am and tell my mom or dad: The fire truck is here!",correct:!0},{text:"I run out onto the street to watch",correct:!1},{text:"I throw my shoe at the truck",correct:!1},{text:"I get scared and hide from the firefighters",correct:!1}]}},{id:26,icon:"FireExtinguisher",emoji:"🧯",accent:"#dc2626",title:"The red bottle that puts out fires",subtitle:"What is a fire extinguisher?",summary:"At home, at school and in offices, there is an important red bottle. It is called a fire extinguisher. Grown-ups use it to put out small fires. You don't use it, but it is good to know what it is and where it is.",blocks:[{heading:"It is only for grown-ups",body:"A fire extinguisher is heavy, and there is strong pressure inside it. Children never use a fire extinguisher. If a fire starts, get out of there and call a grown-up in a loud voice.",image:"media/images/ext_adult.png"},{heading:"Different types, different uses",body:"There are different kinds of fire extinguishers. You can't tell from the color alone which fire each one is for. The words and pictures on it show what it is for. A grown-up who has been trained picks the right one. You stay away and tell a grown-up.",image:"media/images/ext_colors.png"},{heading:"Where is the fire extinguisher in your home?",body:`Ask your mom and dad: "Where is our fire extinguisher?" It is often near the kitchen door or in the hallway. Know where it is, but don't touch it.`,image:"media/images/ext_location.png"}],examples:["A fire extinguisher is heavy, and you can't lift it. It is for grown-ups.","If there is a fire in a socket or in an electric device, don't pour water on it! The electricity will shock you. Tell a grown-up right away.","Grown-ups check the fire extinguisher every month and take it to an expert once a year, so it is always ready."],video:"media/videos/lesson26_extinguisher.mp4",game:{instruction:"When you see a small fire, what will you do?",items:[{text:"I shout: Fire! and get out fast",emoji:"🏃",correct:!0},{text:"I try to use the fire extinguisher",emoji:"🧯",correct:!1},{text:"I tell a grown-up",emoji:"👨",correct:!0},{text:"I pour water on the fire myself",emoji:"💧",correct:!1}]},activity:{prompt:`You see the red bottle in the hallway. Your friend says: "Come on, let's play with it!" What will you do?`,image:"media/images/activity_ext.png",options:[{text:"I tell my friend: No! This is not a toy, it is for putting out fires. Then I tell a grown-up",correct:!0},{text:"We will play with it together",correct:!1},{text:"I will pull out the safety pin",correct:!1},{text:"I will push it until it falls on the floor",correct:!1}]}},{id:27,icon:"HeartHandshake",emoji:"❤️‍🩹",accent:"#db2777",title:"Helping a hurt friend",subtitle:"If your friend falls, what will you do?",summary:"When a friend falls or gets hurt, you can help. You are not a doctor, but you can stay calm and quickly tell a grown-up. Grown-ups know what to do, and if it is needed, they call the ambulance (122).",blocks:[{heading:"First: stay calm",body:`Crying doesn't help. Stay close to your friend and ask: "Are you OK?" Then say: "Don't be scared, I will call a grown-up."`,image:"media/images/help_calm.png"},{heading:"Second: call a grown-up",body:'Call out quickly and loudly: "Teacher!" or "Mom!" If there is no grown-up nearby, go quickly and bring a grown-up. The grown-up will call the ambulance (122) if it is needed.',image:"media/images/help_call.png"},{heading:"Third: small ways to help",body:`Until the grown-up comes, you can do these things:

• 🩸 Bleeding: give your friend a clean piece of cloth, so they can press it hard on the cut themselves.
• 🦴 If an arm or a leg hurts a lot: don't move your friend.
• 🔥 Burns: tell a grown-up. They will hold the burned area under cool water for 20 minutes. Ice and toothpaste are not good for burns.`,image:"media/images/help_basic.png"}],examples:["If your friend's head or neck hurts, don't move your friend and don't let them get up. Wait together for a grown-up.","Don't touch other people's blood, and after helping, wash your hands with soap and water.","If you are scared, call a grown-up. Asking for help shows how smart you are."],video:"media/videos/lesson27_first_aid.mp4",game:{instruction:"Which of these are the right things to do for a hurt friend?",items:[{text:"I stay calm and call the grown-ups",emoji:"🧘",correct:!0},{text:"I cry and run away",emoji:"😭",correct:!1},{text:"I give my friend a clean piece of cloth to press on the cut",emoji:"🩹",correct:!0},{text:"I laugh at my friend and keep playing",emoji:"🤡",correct:!1},{text:"I tell a grown-up, so they can call the ambulance (122)",emoji:"📞",correct:!0}]},activity:{prompt:'At school, your friend fell down the stairs and says: "My leg hurts!" What will you do?',image:"media/images/activity_help.png",options:[{text:"I tell my friend: Stay calm! Then I call the teacher, and I don't move my friend.",correct:!0},{text:"I try to pick my friend up and carry them to the kitchen",correct:!1},{text:"I pull my friend's leg to see if it is broken",correct:!1},{text:"I go home and say nothing",correct:!1}]}}],t={lessons:e};export{t as default,e as lessons};
